<template><view class="shop-page"><BusinessPageHeader title="确认订单" fallback="/pages/selection/index"/><view class="shop-body"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="data"><view v-if="data.product.fulfillmentType==='PHYSICAL'" class="shop-card"><button class="shop-beneficiary" :disabled="busy||!!pendingCreation" @click="selectionType='addresses'"><view class="shop-row"><text>收货地址</text><text>{{address?.recipient||'请选择'}} {{address?.phone}}</text></view><text class="shop-muted">{{address?address.regionNames.join('')+address.detail:'请先添加收货地址'}}</text></button><button class="shop-link" @click="manageAddresses">管理收货地址</button></view><view v-if="data.product.requiresMember" class="shop-card"><button class="shop-beneficiary" :disabled="busy||!!pendingCreation" @click="selectionType='members'"><view class="shop-row"><text>选择会员</text><text>{{member?.name||'请选择会员'}}</text></view></button></view><view class="shop-card"><button class="shop-beneficiary" :disabled="busy||!!pendingCreation" @click="selectionType='stores'"><view class="shop-row"><text>所属门店</text><text>{{store?.name||'请选择'}}</text></view><text class="shop-muted">{{store?.address}}</text></button></view><view class="shop-card"><view class="shop-title">共{{draft.quantity}}件商品</view><view class="shop-product-line"><image :src="data.product.coverUrl" mode="aspectFill"/><view><view>{{data.product.title}}</view><text class="shop-tag">{{data.product.skus.find(x=>x.id===draft.skuId)?.label}}</text><view class="shop-muted">×{{draft.quantity}}</view></view></view><view class="shop-row"><text>订单备注</text></view><input v-model="draft.remark" :disabled="busy||!!pendingCreation" class="shop-field" placeholder="请输入订单备注" maxlength="200" @input="invalidate"/><button class="shop-beneficiary" :disabled="busy||!!pendingCreation" @click="couponOpen=true"><view class="shop-row"><text>优惠券</text><text>{{couponOptions.find(x=>x.id===draft.couponId)?.title||'不使用优惠券'}}</text></view></button><view class="shop-row"><text>商品金额</text><text>¥{{quote?money(quote.goodsAmount):'—'}}</text></view><view class="shop-row"><text>优惠金额</text><text>−¥{{quote?money(quote.discountAmount):'—'}}</text></view><view class="shop-row"><text>总计</text><text class="shop-price">¥{{quote?money(quote.payableAmount):'—'}}</text></view><text v-if="operationError" class="shop-error">{{operationError}}</text></view></template></view><view v-if="selectionType" class="shop-mask" @click.self="selectionType=''"><view class="shop-sheet"><view class="shop-sheet-heading"><text class="shop-title">{{{addresses:'选择收货地址',members:'选择会员',stores:'选择所属门店'}[selectionType]}}</text><button class="shop-close" @click="selectionType=''"><image src="/static/common/icon-close.png"/></button></view><view v-if="!selectionRows.length" class="shop-empty">暂无可选内容</view><button v-for="item in selectionRows" :key="item.id" class="shop-card shop-beneficiary" :disabled="busy" @click="chooseEntity(item)"><view>{{selectionType==='addresses'?item.recipient+' '+item.phone:item.name}}</view><text class="shop-muted">{{selectionType==='addresses'?item.display:item.address||item.gradeLabel}}</text></button></view></view><view v-if="couponOpen" class="shop-mask" @click.self="couponOpen=false"><view class="shop-sheet"><view class="shop-sheet-heading"><text class="shop-title">选择优惠券</text><button class="shop-close" @click="couponOpen=false"><image src="/static/common/icon-close.png"/></button></view><button v-for="item in couponOptions" :key="item.id||'none'" class="shop-card shop-beneficiary" :disabled="busy||!!pendingCreation" @click="chooseCoupon(item)"><view class="shop-row"><text>{{item.title}}</text><text class="shop-accent">{{item.amount?'−¥'+money(item.amount):''}}</text></view><text v-if="item.minAmount" class="shop-muted">满{{money(item.minAmount)}}可用</text></button></view></view><view v-if="data" class="shop-footer"><view>合计：<text class="shop-price">¥{{quote?money(quote.payableAmount):'—'}}</text></view><button class="shop-primary" :disabled="busy" @click="submit">{{busy?'处理中…':pendingCreation?'重试原订单提交':quote?'确认订单':'计算金额'}}</button></view></view></template>
<script setup>
import {ref,computed} from 'vue'
import {config} from '../../config'
import {onLoad,onShow,onUnload} from '@dcloudio/uni-app'
import {useAuth} from '../../composables/useAuth'
import {getProduct,getCheckoutOptions,quoteCheckout,createCheckoutOrder,commerceRequestKey,getPendingCheckout,rememberPendingCheckout,clearPendingCheckout,isCheckoutRejection} from '../../services/commerce'
import {money} from '../../features/exclusive/format'
import BusinessPageHeader from '../../components/BusinessPageHeader.vue'
import FeaturePageState from '../../components/FeaturePageState.vue'
useAuth();const selectionType=ref(''),pendingCreation=ref(null),couponOpen=ref(false),data=ref(null),status=ref('loading'),error=ref(''),operationError=ref(''),busy=ref(false),quote=ref(null),draft=ref({quantity:1,remark:'',couponId:null});let epoch=0,active=true,quoteEpoch=0,attemptKey='',submitted=false
const selectionRows=computed(()=>data.value?.options[selectionType.value]||[])
function chooseEntity(item){const field={addresses:'addressId',members:'memberId',stores:'storeId'}[selectionType.value];if(!field)return;draft.value[field]=item.id;selectionType.value='';invalidate();calculate()}
const address=computed(()=>data.value?.options.addresses.find(x=>x.id===draft.value.addressId)),addressIndex=computed(()=>Math.max(0,data.value?.options.addresses.findIndex(x=>x.id===draft.value.addressId)||0)),member=computed(()=>data.value?.options.members.find(x=>x.id===draft.value.memberId)),store=computed(()=>data.value?.options.stores.find(x=>x.id===draft.value.storeId)),couponOptions=computed(()=>[{id:null,title:'不使用优惠券'},...(data.value?.options.coupons||[])])
function invalidate(){if(pendingCreation.value)return;++quoteEpoch;quote.value=null;attemptKey='';operationError.value=''}
async function calculate(){if(!data.value)return;const current=++quoteEpoch;quote.value=null;try{const result=await quoteCheckout({...draft.value});if(active&&current===quoteEpoch){quote.value=result;attemptKey=commerceRequestKey()}}catch(e){if(active&&current===quoteEpoch)operationError.value=e.message}}
function chooseCoupon(item){draft.value.couponId=item.id;couponOpen.value=false;invalidate();calculate()}
function select(field,rows,event){draft.value[field]=rows[Number(event.detail.value)]?.id||null;invalidate();calculate()}
async function load(){const current=++epoch;status.value='loading';try{const [product,options]=await Promise.all([getProduct(draft.value.productId),getCheckoutOptions()]);if(!active||current!==epoch)return;options.addresses=options.addresses.map(x=>({...x,display:`${x.recipient} ${x.regionNames.join('')}${x.detail}`}));data.value={product,options};if(!draft.value.storeId)draft.value.storeId=options.stores[0]?.id;const selected=options.addresses.find(x=>x.id===draft.value.addressId)||options.addresses.find(x=>x.isDefault);draft.value.addressId=selected?.id;status.value='ready';if(pendingCreation.value){quote.value=pendingCreation.value.quote;attemptKey=pendingCreation.value.key;return}invalidate();await calculate()}catch(e){if(current===epoch){error.value=e.message;status.value='error'}}}
async function submit(){if(busy.value||submitted)return;busy.value=true;operationError.value='';try{if(!quote.value){await calculate();return}if(!pendingCreation.value)pendingCreation.value=rememberPendingCheckout(draft.value,quote.value,attemptKey);const intent=pendingCreation.value;const result=await createCheckoutOrder(intent.quote.id,intent.key);clearPendingCheckout(intent.draft);if(!active)return;submitted=true;uni.redirectTo({url:`/pages/payment/cashier?orderId=${encodeURIComponent(result.order.id)}`})}catch(e){if(active){operationError.value=e.message;if(config.useMock||isCheckoutRejection(e)){clearPendingCheckout(draft.value);pendingCreation.value=null;quote.value=null}}}finally{if(active)busy.value=false}}
function manageAddresses(){if(pendingCreation.value)return;invalidate();uni.navigateTo({url:'/pages/address/list'})}
let initialized=false;onLoad(q=>{draft.value={...draft.value,productId:q.productId||'',skuId:q.skuId||'',quantity:Number(q.quantity||1)};const pending=getPendingCheckout(draft.value);if(pending){pendingCreation.value=pending;draft.value={...pending.draft};quote.value=pending.quote;attemptKey=pending.key}initialized=true});onShow(()=>{if(initialized&&!submitted)load()});onUnload(()=>{active=false;++epoch;++quoteEpoch})
</script><style>@import '../../styles/commerce.css';</style>
